    for c in range(15):
        inp = test_input[r][c]
        if inp not in noise:
            continue

        is_4way = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 27 and 0 <= nc < 15:
                if test_input[nr][nc] == inp:
                    is_4way = False
                    break
        if is_4way:
            single_4way_noisy.append((r, c, inp))

print(f"Noisy single cells (4-way): {len(single_4way_noisy)}")
for r, c, inp in sorted(single_4way_noisy):
    print(f"  ({r},{c}): {inp}")

# Transform
bg = 3
output = [row[:] for row in test_input]

for r, c, inp in single_4way_noisy:
    neighbors = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 27 and 0 <= nc < 15:
            neighbors.append(test_input[nr][nc])

    n_bg = sum(1 for n in neighbors if n == bg)
    fg_neighbors = [n for n in neighbors if n in fg]
    n_fg = len(fg_neighbors)

    if n_fg >= n_bg:
        output[r][c] = Counter(fg_neighbors).most_common(1)[0][0] if fg_neighbors else bg
    else:
        output[r][c] = bg

print("\nFinal grid:")
for row in output:
    print(' '.join(map(str, row)))

